const cfg=$('Config').first().json;
const cv=$('CV Text').first().json.text||'';
const schema={type:'object',properties:{
 reasoning:{type:'string'},
 search_terms:{type:'array',items:{type:'string'}},
 contract_types:{type:'array',items:{type:'string'}},
 locations:{type:'array',items:{type:'string'}},
 remote_only:{type:'boolean'},
 languages:{type:'array',items:{type:'string'}},
 exclude_keywords:{type:'array',items:{type:'string'}}},
 required:['reasoning','search_terms','contract_types','locations','remote_only','languages','exclude_keywords']};
const system=`You are a job-search planner. Think step by step in "reasoning": what contract type does the user want (PFE, internship, CDI, CDD, freelance, apprenticeship), which locations or remote, which seniority, which languages, which domains. Use the CV only to pick relevant domain keywords. Then output 3 to 5 short search_terms (job titles or keywords, mix English and French when relevant, no more than 4 words each), contract_types, locations (cities or countries, empty if remote only), remote_only, languages, exclude_keywords (titles to avoid, e.g. senior, manager when the user wants a junior or internship role).`;
const user=`USER REQUEST:\n${cfg.request}\n\nCANDIDATE CV:\n${cv.slice(0,6000)}`;
return [{json:{ollamaBody:{model:cfg.model,stream:false,format:schema,options:{temperature:0.2,num_ctx:8192},messages:[{role:'system',content:system},{role:'user',content:user}]}}}];

function parseLLM(r){let t=(r&&r.message&&r.message.content)||'';t=t.replace(/^\s*```(?:json)?/i,'').replace(/```\s*$/,'').trim();try{return JSON.parse(t);}catch(e){const m=t.match(/\{[\s\S]*\}/);if(m){try{return JSON.parse(m[0]);}catch(e2){}}return null;}}
const cfg=$('Config').first().json;
let p=parseLLM($input.first().json);
if(!p||!Array.isArray(p.search_terms)||!p.search_terms.length){p={reasoning:'fallback',search_terms:[String(cfg.request).slice(0,60)],contract_types:[],locations:[],remote_only:false,languages:[],exclude_keywords:[]};}
return [{json:p}];

const plan=$('Parse Plan').first().json;
const terms=(plan.search_terms||[]).map(s=>String(s).toLowerCase());
const tokens=[...new Set(terms.join(' ').split(/[^a-zà-ÿ0-9+#.]+/).filter(w=>w.length>3))];
const excl=(plan.exclude_keywords||[]).map(s=>String(s).toLowerCase()).filter(Boolean);
const strip=h=>String(h||'').replace(/<[^>]+>/g,' ').replace(/&nbsp;/g,' ').replace(/&amp;/g,'&').replace(/\s+/g,' ').trim();
const emailRe=/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g;
const get=n=>{try{return $(n).all().map(i=>i.json);}catch(e){return [];}};
const now=new Date().toISOString();
const seen=new Set();const jobs=[];
const push=(source,id,o)=>{
  const url=String(o.url||'').split('?')[0];
  const job_id=source+':'+(id||url);
  if(!o.title||!url||seen.has(job_id))return;
  const title=String(o.title);
  if(excl.some(k=>title.toLowerCase().includes(k)))return;
  const desc=strip(o.description).slice(0,3500);
  const emails=(desc.match(emailRe)||[]).filter(e=>!/no-?reply|example\.|sentry|wixpress/i.test(e));
  seen.add(job_id);
  jobs.push({json:{job_id,found_at:now,source,title,company:o.company||'',location:o.location||'',url:o.url,apply_email:emails[0]||'',description:desc}});
};
const relevant=(title,tags)=>{const h=(title+' '+(tags||[]).join(' ')).toLowerCase();return !tokens.length||tokens.some(t=>h.includes(t));};
for(const r of get('Remotive'))for(const j of (r.jobs||[]))push('remotive',j.id,{title:j.title,company:j.company_name,location:j.candidate_required_location||'Remote',url:j.url,description:j.description});
for(const j of get('RemoteOK')){if(!j.position)continue;if(!relevant(j.position,j.tags))continue;push('remoteok',j.id,{title:j.position,company:j.company,location:j.location||'Remote',url:j.url||j.apply_url,description:j.description});}
for(const r of get('Arbeitnow'))for(const j of (r.data||[])){if(!relevant(j.title,j.tags))continue;push('arbeitnow',j.slug,{title:j.title,company:j.company_name,location:(j.location||'')+(j.remote?' (Remote)':''),url:j.url,description:j.description});}
for(const r of get('Jooble'))for(const j of (r.jobs||[]))push('jooble',j.id,{title:j.title,company:j.company,location:j.location,url:j.link,description:j.snippet});
return jobs;

const cfg=$('Config').first().json;
let rows=[];try{rows=$('Read Applications Sheet').all().map(i=>i.json);}catch(e){}
const seen=new Set(),seenCT=new Set();
for(const r of rows){if(!r.job_id)continue;if(['to_apply','error'].includes(r.status))continue;seen.add(r.job_id);seenCT.add(((r.company||'')+'|'+(r.title||'')).toLowerCase());}
const out=[],used=new Set();
for(const it of $('Normalize').all()){const j=it.json;const ct=((j.company||'')+'|'+(j.title||'')).toLowerCase();
  if(seen.has(j.job_id)||seenCT.has(ct)||used.has(ct))continue;used.add(ct);out.push({json:j});if(out.length>=Number(cfg.maxEvaluate))break;}
return out;

const cfg=$('Config').first().json;
const cv=$('CV Text').first().json.text||'';
const plan=$('Parse Plan').first().json;
const schema={type:'object',properties:{
 reasoning:{type:'string'},matched_skills:{type:'array',items:{type:'string'}},missing_skills:{type:'array',items:{type:'string'}},
 contract_fit:{type:'boolean'},location_fit:{type:'boolean'},score:{type:'integer'},verdict:{type:'string',enum:['apply','skip']},apply_angle:{type:'string'}},
 required:['reasoning','matched_skills','missing_skills','contract_fit','location_fit','score','verdict','apply_angle']};
const system=`You are a rigorous technical recruiter judging the fit between ONE candidate and ONE job. Use ONLY facts written in the CV. Never assume or infer skills that are not written there.
Work step by step inside "reasoning": (1) list the job's hard requirements, (2) for each one give the CV evidence or write MISSING, (3) check contract type, location and language against the user's request, (4) conclude.
Score 0-100: 85+ strong match, 70-84 good, 50-69 partial, below 50 poor. A missing hard requirement caps the score at 69. verdict is "apply" only if score >= ${cfg.minScore} and contract_fit and location_fit are true, otherwise "skip". apply_angle: one sentence on the strongest truthful argument for this candidate.`;
return $input.all().map(it=>{const j=it.json;
 const user=`USER REQUEST:\n${cfg.request}\nPLAN: contract types=${(plan.contract_types||[]).join(', ')}; locations=${(plan.locations||[]).join(', ')}; remote_only=${plan.remote_only}\n\nCANDIDATE CV:\n${cv.slice(0,6000)}\n\nJOB:\nTitle: ${j.title}\nCompany: ${j.company}\nLocation: ${j.location}\nSource: ${j.source}\nDescription: ${j.description}`;
 return {json:{...j,ollamaBody:{model:cfg.model,stream:false,format:schema,options:{temperature:0.1,num_ctx:8192},messages:[{role:'system',content:system},{role:'user',content:user}]}}};});

function parseLLM(r){let t=(r&&r.message&&r.message.content)||'';t=t.replace(/^\s*```(?:json)?/i,'').replace(/```\s*$/,'').trim();try{return JSON.parse(t);}catch(e){const m=t.match(/\{[\s\S]*\}/);if(m){try{return JSON.parse(m[0]);}catch(e2){}}return null;}}
const cfg=$('Config').first().json;const out=[];
$input.all().forEach((it,i)=>{
  const {ollamaBody,description,...job}=$('Match Prompt').itemMatching(i).json;
  const m=parseLLM(it.json);if(!m||typeof m.score!=='number')return;
  const ok=m.score>=Number(cfg.minScore)&&m.verdict==='apply';
  out.push({json:{...job,description:$('Match Prompt').itemMatching(i).json.description,score:m.score,verdict:m.verdict,reasoning:m.reasoning,matched_skills:m.matched_skills||[],missing_skills:m.missing_skills||[],apply_angle:m.apply_angle||'',status:ok?'to_apply':'skipped_low_score'}});
});
return out;

const COLS=['job_id','found_at','source','title','company','location','url','apply_email','score','verdict','reasoning','matched_skills','missing_skills','status','cover_letter','letter_check','applied_at','thread_id','last_message_id','follow_up_count','last_contact_at'];
const toRow=j=>{const r={};for(const c of COLS){const v=j[c];r[c]=Array.isArray(v)?v.join(', '):(v??'');}return r;};
return $input.all().map(it=>({json:toRow(it.json)}));

const cfg=$('Config').first().json;
const cv=$('CV Text').first().json.text||'';
const schema={type:'object',properties:{reasoning:{type:'string'},subject:{type:'string'},body:{type:'string'}},required:['reasoning','subject','body']};
const system=`You write one job application email for ONE candidate.
ABSOLUTE RULES:
1. Every statement about the candidate must be directly supported by the CV text. Never invent skills, tools, years of experience, degrees, employers, certifications, projects, metrics, grades or availability dates.
2. Skills in the MISSING list must not be claimed. Either omit them or say plainly that the candidate is looking to learn them, only if that is natural.
3. Write in the language of the job posting (French or English).
4. 170 to 230 words, 3 short paragraphs, professional, specific to this company and role, no cliches, no placeholders, no brackets.
5. Mention once that the CV is attached.
6. Sign with the candidate name.
In "reasoning" list the exact CV facts you used. "subject" is a short application subject line containing the job title.`;
return $input.all().map(it=>{const j=it.json;
 const user=`CANDIDATE NAME: ${cfg.candidateName}\n\nCV:\n${cv.slice(0,6000)}\n\nJOB:\nTitle: ${j.title}\nCompany: ${j.company}\nLocation: ${j.location}\nDescription: ${j.description}\n\nMATCHED SKILLS: ${(j.matched_skills||[]).join(', ')}\nMISSING SKILLS (do not claim): ${(j.missing_skills||[]).join(', ')}\nSTRONGEST TRUTHFUL ANGLE: ${j.apply_angle}`;
 return {json:{...j,ollamaBody:{model:cfg.model,stream:false,format:schema,options:{temperature:0.4,num_ctx:8192},messages:[{role:'system',content:system},{role:'user',content:user}]}}};});

function parseLLM(r){let t=(r&&r.message&&r.message.content)||'';t=t.replace(/^\s*```(?:json)?/i,'').replace(/```\s*$/,'').trim();try{return JSON.parse(t);}catch(e){const m=t.match(/\{[\s\S]*\}/);if(m){try{return JSON.parse(m[0]);}catch(e2){}}return null;}}
const out=[];
$input.all().forEach((it,i)=>{const {ollamaBody,...job}=$('Letter Prompt').itemMatching(i).json;
 const l=parseLLM(it.json);if(!l||!l.body||!l.subject)return;
 out.push({json:{...job,subject:l.subject,body:l.body,cover_letter:l.body}});});
return out;

const cfg=$('Config').first().json;
const cv=$('CV Text').first().json.text||'';
const schema={type:'object',properties:{checked_claims:{type:'array',items:{type:'object',properties:{claim:{type:'string'},supported:{type:'boolean'}},required:['claim','supported']}},unsupported_claims:{type:'array',items:{type:'string'}},verdict:{type:'string',enum:['pass','fail']}},required:['checked_claims','unsupported_claims','verdict']};
const system=`You are a strict fact checker. Compare a cover letter against the candidate CV. Extract every factual claim the letter makes about the candidate (skills, tools, experience, education, projects, numbers, dates, certifications). For each, decide supported=true only if the CV text clearly supports it. Generic enthusiasm and statements about the company are not claims. verdict is "pass" only if unsupported_claims is empty.`;
return $input.all().map(it=>{const j=it.json;
 const user=`CV:\n${cv.slice(0,6000)}\n\nCOVER LETTER:\n${j.body}`;
 return {json:{...j,ollamaBody:{model:cfg.model,stream:false,format:schema,options:{temperature:0,num_ctx:8192},messages:[{role:'system',content:system},{role:'user',content:user}]}}};});

function parseLLM(r){let t=(r&&r.message&&r.message.content)||'';t=t.replace(/^\s*```(?:json)?/i,'').replace(/```\s*$/,'').trim();try{return JSON.parse(t);}catch(e){const m=t.match(/\{[\s\S]*\}/);if(m){try{return JSON.parse(m[0]);}catch(e2){}}return null;}}
const cfg=$('Config').first().json;
const cv=$('Read CV').first().binary.cv;
return $input.all().map((it,i)=>{
 const {ollamaBody,description,...j}=$('Verify Prompt').itemMatching(i).json;
 const v=parseLLM(it.json);
 const bad=(v&&Array.isArray(v.unsupported_claims))?v.unsupported_claims:['verification failed'];
 const ok=!!v&&v.verdict==='pass'&&bad.length===0;
 j.letter_check=ok?'pass':('fail: '+bad.join(' | '));
 let route;
 if(!ok){route='review';j.status='needs_review';}
 else if(!j.apply_email){route='review';j.status='manual_apply';}
 else if(cfg.dryRun){route='draft';}
 else{route='send';}
 return {json:{...j,route},binary:{cv:{...cv,fileName:cfg.cvFileName}}};});

const COLS=['job_id','found_at','source','title','company','location','url','apply_email','score','verdict','reasoning','matched_skills','missing_skills','status','cover_letter','letter_check','applied_at','thread_id','last_message_id','follow_up_count','last_contact_at'];
const toRow=j=>{const r={};for(const c of COLS){const v=j[c];r[c]=Array.isArray(v)?v.join(', '):(v??'');}return r;};
return $input.all().map((it,i)=>{const {binary,...j}=$('Route').itemMatching(i).json;const now=new Date().toISOString();
 const ok=!!it.json.threadId;
 return {json:toRow({...j,status:ok?'applied':'error',applied_at:ok?now:'',thread_id:it.json.threadId||'',last_message_id:it.json.id||'',follow_up_count:0,last_contact_at:ok?now:''})};});

